pub struct Person { courses: Vec<Course> }        // private field: no `pub`

impl Person {
    pub fn courses(&self) -> &[Course] { &self.courses }        // shared view, no copy

    pub fn add_course(&mut self, c: Course) -> Result<(), Error> {
        validate(&c)?;
        self.courses.push(c);
        Ok(())
    }

    pub fn remove_course(&mut self, c: &Course) {
        self.courses.retain(|x| x != c);
    }
}
